// ============================================================
// Validar día — TFO Listar disponibilidad día v1
// ------------------------------------------------------------
// Input: { fecha } — 'YYYY-MM-DD' o ISO completo (se toma la fecha, zona CDMX).
// Reglas (America/Mexico_City):
//   - Fecha parseable
//   - No anterior a hoy (día pasado -> fecha_pasada)
//   - Lunes a Viernes (weekday 1..5)
// Si falla -> shape final NO_VALIDO listo para el agente.
// Si pasa   -> fecha_dia_inicio / fecha_dia_fin (ISO CDMX) para el nodo Calendar.
// ============================================================

const TZ = 'America/Mexico_City';
const inp = $input.first().json;
const fechaRaw = (inp.fecha || '').toString().trim();

const makeFail = (motivo, mensaje) => [{
  json: {
    valid: false,
    status: 'NO_VALIDO',
    motivo,
    mensaje,
    slots_libres: [],
    fecha: fechaRaw
  }
}];

if (!fechaRaw) {
  return makeFail(
    'formato_invalido',
    'No me pasaron la fecha del día a consultar. Pedile al lead que indique el día (ej: "el viernes").'
  );
}

// Parseo ISO en CDMX; fallback a solo la parte de fecha
let dt = DateTime.fromISO(fechaRaw, { zone: TZ });
if (!dt.isValid) {
  dt = DateTime.fromISO(fechaRaw.substring(0, 10), { zone: TZ });
}
if (!dt.isValid) {
  return makeFail(
    'formato_invalido',
    'No pude entender la fecha. Pedile al lead que indique el día claramente (ej: "el jueves" o "9 de julio").'
  );
}

const dia = dt.startOf('day');
const hoy = DateTime.now().setZone(TZ).startOf('day');

// Día anterior a hoy
if (dia < hoy) {
  return makeFail(
    'fecha_pasada',
    'Esa fecha ya pasó. Proponé un día futuro (lunes a viernes).'
  );
}

// Lunes a Viernes
if (dia.weekday > 5) {
  return makeFail(
    'no_laboral',
    'Solo tomamos reuniones de lunes a viernes. Proponé un día hábil.'
  );
}

// VÁLIDO
return [{
  json: {
    valid: true,
    fecha: dia.toISODate(),
    dia_humano: dia.setLocale('es').toFormat("cccc d 'de' LLLL"),
    fecha_dia_inicio: dia.toISO(),
    fecha_dia_fin: dia.endOf('day').toISO()
  }
}];

// ============================================================
// Calcular slots libres — TFO Listar disponibilidad día v1
// ------------------------------------------------------------
// Cruza los 6 slots canónicos CDMX contra los bookedSlots del calendar.
// - bookedSlots vienen como items {start, end} (ISO). Si el día está vacío,
//   $input.all() puede venir vacío o con un item sin start/end (alwaysOutputData).
// - Si el día consultado es HOY, descarta slots que ya pasaron (< ahora CDMX).
// Devuelve el shape final para el agente: {status, fecha, dia_humano, slots_libres, mensaje}
// ============================================================

const TZ = 'America/Mexico_City';
const val = $('Validar día').first().json;

// Los 6 slots canónicos en CDMX (en punto y y media). Cada reunión dura 30 min.
// OJO: mantener sincronizado con la ventana que valida check_disponibilidad.
const SLOTS_CDMX = ['10:00', '10:30', '11:00', '11:30', '12:00', '12:30'];

const dia = DateTime.fromISO(val.fecha_dia_inicio, { zone: TZ }).startOf('day');
const now = DateTime.now().setZone(TZ);

// Slots ocupados desde el nodo Calendar (outputFormat bookedSlots -> {start, end})
const ocupados = $input.all()
  .map(s => s.json)
  .filter(s => s && s.start && s.end)
  .map(s => ({
    start: DateTime.fromISO(s.start, { zone: TZ }),
    end: DateTime.fromISO(s.end, { zone: TZ })
  }));

// Solapamiento de intervalos [s1,e1) vs [s2,e2)
const solapa = (s1, e1, s2, e2) => s1 < e2 && s2 < e1;

const libres = [];
for (const hhmm of SLOTS_CDMX) {
  const [h, m] = hhmm.split(':').map(Number);
  const ini = dia.set({ hour: h, minute: m, second: 0, millisecond: 0 });
  const fin = ini.plus({ minutes: 30 });
  // Descartar slots que ya pasaron (solo aplica si el día es hoy)
  if (ini <= now) continue;
  const ocupado = ocupados.some(o => solapa(ini, fin, o.start, o.end));
  if (!ocupado) libres.push(hhmm);
}

const mensaje = libres.length > 0
  ? `Slots libres para ${val.dia_humano} (hora México, CDMX): ${libres.join(', ')}.`
  : `No hay cupos disponibles para ${val.dia_humano}. Proponé otro día hábil (lunes a viernes).`;

return [{
  json: {
    status: 'OK',
    fecha: val.fecha,
    dia_humano: val.dia_humano,
    slots_libres: libres,
    mensaje
  }
}];
